/** Source: fldeff_misc.c → Task_PopSecretBaseBalloon */
export const Task_PopSecretBaseBalloon: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;

      if (data[3] == 6)
          data[3] = 0;
      else
          data[3]++;

      if (data[3] == 0)
      {
          if (data[4] == 2)
              DoBalloonSoundEffect(data[0]);

          MapGridSetMetatileIdAt(data[1], data[2], data[0] + data[4]);
          CurrentMapDrawMetatileAt(data[1], data[2]);

          if (data[4] == 3)
              rt.DestroyTask(taskId);
          else
              data[4]++;
      }
};

