/** Source: fldeff_misc.c → Task_WateringBerryTreeAnim_Start */
export const Task_WateringBerryTreeAnim_Start: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let playerObjEvent: any = gObjectEvents[gPlayerAvatar.objectEventId];

      if (!ObjectEventIsMovementOverridden(playerObjEvent)
          || ObjectEventClearHeldMovementIfFinished(playerObjEvent))
      {
           
          SetPlayerAvatarWatering(GetPlayerFacingDirection());
          ObjectEventSetHeldMovement(playerObjEvent, GetWalkInPlaceNormalMovementAction(GetPlayerFacingDirection()));
          task.func = (t) => Task_WateringBerryTreeAnim_Continue(t, rt);
      }
};

/** Source: fldeff_misc.c → Task_WateringBerryTreeAnim_Continue */
export const Task_WateringBerryTreeAnim_Continue: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let playerObjEvent: any = gObjectEvents[gPlayerAvatar.objectEventId];

      if (ObjectEventClearHeldMovementIfFinished(playerObjEvent))
      {
          let value = task.data[1]++;

           
          if (value < 10)
              ObjectEventSetHeldMovement(playerObjEvent, GetWalkInPlaceNormalMovementAction(GetPlayerFacingDirection()));
          else
              task.func = (t) => Task_WateringBerryTreeAnim_End(t, rt);
      }
};

